import { defineConfig } from 'astro/config';
import { locales, defaultLocale } from './src/i18n/config';

// Same conventions as openbiblestories.org: English at /, every other locale
// at /{lang}/, trailing slashes everywhere, uncompressed HTML.
//
// Sitemaps are generated by src/pages/sitemap-*.xml.ts (an index plus one
// file for the marketing pages and one for the /tc-help/ pages) rather than
// @astrojs/sitemap, which cannot add hreflang alternates per URL the way
// these do.
export default defineConfig({
  site: 'https://translationcore.com',
  devToolbar: { enabled: false },
  trailingSlash: 'always',

  // Keep the built HTML uncompressed so it stays diffable against the
  // hand-written pages this site was migrated from.
  compressHTML: false,

  i18n: {
    defaultLocale,
    locales: locales.map((l) => l.code),
    routing: {
      prefixDefaultLocale: false,
    },
  },
});
